interface Printable {
    default void print() {
        System.out.print("Printable ");
    }
}
interface Showable {
    default void print() {
        System.out.print("Showable ");
    }
}
class Demo implements Printable, Showable {
    public void print() {
        Printable.super.print();
        Showable.super.print();
    }
}
new Demo().print();

